# Mixture-of-experts routing written out: router logits, probabilities, top-k masks, Switch-style gates, dispatch tables, load, entropy, and the balance loss.

def u:router_logits(h, Wr, br) {
  "Router scores [T, E]: one linear layer over the hidden state.";
  matmul(h, Wr) + br
}

def u:router_probs(logits) {
  "Router probabilities [T, E]: softmax over experts for each token.";
  softmax(logits)
}

def u:top1_mask(logits, E) {
  "One-hot [T, E] selecting each token's highest-scoring expert; a stop-gradient constant on the tape.";
  one_hot(argmax(logits, 1), E)
}

def u:topk_mask(logits, k, E) {
  "0/1 [T, E] selecting each token's k highest-scoring experts, built eagerly row by row.";
  T = reduce_mul(shape(take(logits, 1, 0)));
  mask = fill([0, E], 0);
  t = 0;
  while lt(t, T) {
    row = reduce_add(one_hot(argtop_k(take(logits, 0, t), k), E), 0);
    mask = concat(mask, reshape(row, [1, E]), 0);
    t = t + 1
  };
  mask
}

def u:switch_gate(logits, E) {
  "Switch-style gate [T, E]: the selected expert's probability, zero elsewhere, so the router receives a gradient.";
  u:router_probs(logits) * u:top1_mask(logits, E)
}

def u:renormalized_gate(probs, mask) {
  "Gate [T, E] whose selected entries are renormalized to sum to one per token (top-k combine).";
  kept = probs * mask;
  kept / reduce_add(kept, 1)
}

def u:gate_column(gate, e, T) {
  "Column e of a gate as a [T, 1] factor to scale one expert's output.";
  reshape(take(gate, 1, e), [T, 1])
}

def u:expert_load(mask) {
  "Tokens routed to each expert, [E].";
  reduce_add(mask, 0)
}

def u:router_entropy(probs) {
  "Mean per-token entropy of the router distribution in nats; log(E) means indifferent, zero means certain.";
  0 - mean(reduce_add(probs * log(probs + 0.000000000001), 1))
}

def u:balance_loss(probs, mask, E, T) {
  "Switch load-balance term: E times the sum over experts of routed fraction times mean probability; equals one when perfectly balanced (T is explicit: size arithmetic is not traced, F12).";
  fraction = reduce_add(mask, 0) / T;
  importance = reduce_add(probs, 0) / T;
  E * reduce_add(fraction * importance)
}

def u:dispatch_rows(x, mask_col) {
  "The rows of x [T, d] routed to one expert: those whose mask column entry is one, in token order.";
  compress(mask_col, x)
}

def u:dispatch_gate(gate_col, mask_col) {
  "The gate values of the routed rows as a [n_e, 1] factor.";
  kept = compress(mask_col, gate_col);
  reshape(kept, [reduce_mul(shape(kept)), 1])
}

def u:place_rows(rows, mask_col, T) {
  "Scatter an expert's [n_e, d] outputs back to their token positions in a [T, d] array (zeros elsewhere) with a one-hot selection matrix.";
  positions = compress(mask_col, range(T));
  matmul(transpose(one_hot(positions, T)), rows)
}

def u:dispatch_cost(mask, p_expert, p_shared) {
  "Parameters touched per token under sparse dispatch versus dense-masked evaluation: {sparse, dense, evals_sparse, evals_dense}.";
  T = reduce_mul(shape(take(mask, 1, 0)));
  E = reduce_mul(shape(take(mask, 0, 0)));
  k = reduce_add(mask) / T;
  {sparse: p_shared + k * p_expert, dense: p_shared + E * p_expert, evals_sparse: k, evals_dense: E}
}

def u:top2_mask(logits, E) {
  "0/1 [T, E] selecting each token's two highest-scoring experts, built from two argmax passes so it traces as a constant on the tape.";
  first = one_hot(argmax(logits, 1), E);
  second = one_hot(argmax(logits - first * 1000000000, 1), E);
  first + second
}

def u:top2_gate(logits, E, ones_ee) {
  "Top-2 gate [T, E]: the two selected probabilities renormalized per token; ones_ee is a constant [E, E] ones matrix passed in so row sums replicate by matmul (nested shape arguments are not traced, F11).";
  probs = u:router_probs(logits);
  kept = probs * u:top2_mask(logits, E);
  kept / matmul(kept, ones_ee)
}

def u:row_normalize(counts) {
  "Each row of a count matrix divided by its row total (rows with no counts become zero).";
  totals = reduce_add(counts, 1);
  counts / reshape(totals + eq(totals, 0), [reduce_mul(shape(totals)), 1])
}

def u:specialization_score(counts) {
  "Mean over families of the largest expert share of that family's tokens; 1/E when routing ignores the family, 1 when each family uses one expert.";
  shares = u:row_normalize(counts);
  n = reduce_mul(shape(take(shares, 1, 0)));
  total = 0;
  i = 0;
  while lt(i, n) {
    total = total + reduce(:max, take(shares, 0, i));
    i = i + 1
  };
  total / n
}

def u:delta_expand(E, r) {
  "Constant block one-hot [E, E*r] that repeats each expert's gate value r times, so a [T, E] gate becomes a [T, E*r] factor by matmul.";
  transpose(one_hot(floor(range(E * r) / r), E))
}

def u:delta_out(x, A_all, B_all, gate, expand) {
  "Gated sum over low-rank delta experts in two matmuls: (x @ A_all) scaled per column by the expanded gate, then @ B_all; exact for any E and k.";
  matmul(matmul(x, A_all) * matmul(gate, expand), B_all)
}

def u:delta_params(d, r) {
  "Trainable parameters of one rank-r delta expert over width d.";
  2 * d * r
}

def u:router_macs(d, E) {
  "Multiply-adds per token spent choosing experts: one d-by-E matmul row plus the bias adds.";
  d * E + E
}
