cat >> lib/docent.mlpl <<'EOF'

def u:docent_logits_n(ids, mask, n) {
  "No-FFN variant (SAN01): the intent and destination heads read the pooled hashed embedding directly; there is no hidden layer and no nonlinearity, so the model is a linear classifier over pooled features.";
  pooled = u:docent_pooled(ids, mask, n);
  {intent: apply(docent_head_i, pooled), dest: apply(docent_head_d, pooled)}
